### Flutter `socket_io_client` Configuration

```dart
import 'package:socket_io_client/socket_io_client.dart' as IO;

final socket = IO.io(
  'http://localhost:3000',
  IO.OptionBuilder()
    .setTransports(['websocket', 'polling'])
    .disableAutoConnect()
    .setAuth({'token': accessToken})
    .setQuery({'token': accessToken})
    .build(),
);

socket.connect();

socket.onConnect((_) => print('Connected: ${socket.id}'));
socket.onDisconnect((_) => print('Disconnected'));
socket.on('message:new', (data) => handleNewMessage(data));
socket.on('conversation:receipt', (data) => handleReceipt(data));
socket.on('typing', (data) => handleTyping(data));
socket.on('conversation:closed', (data) => handleClosed(data));
```

### JavaScript / Web Client Configuration

```javascript
import { io } from 'socket.io-client';

const socket = io('http://localhost:3000', {
  auth: { token: accessToken },
  query: { token: accessToken },
  transports: ['websocket', 'polling']
});
```

